#include <stdio.h>

void draw(int n);

int main(void)
{
    draw(3);
}

void draw(int n)
{
    if (n <= 0)
    {
        return;
    }
    draw(n - 1);
    for (int i = 0; i < n; i++)
    {
        printf("#");
    }
    printf("\n");
}

#include <stdio.h>

int sum(int n);

int main(void)
{
    printf("%i\n", sum(4));
}

int sum(int n)
{
    if (n == 0)
    {
        return 0;
    }
    return n + sum(n - 1);
}

int count(int n)
{
    if (n == 0)
    {
        return 0;
    }
    return 1 + count(n);
}

#include <stdio.h>

int main(void)
{
    int left[] = {3, 6};
    int right[] = {1, 4};
    int i = 0;
    int j = 0;
    while (i < 2 && j < 2)
    {
        if (left[i] < right[j])
        {
            printf("%i ", left[i]);
            i++;
        }
        else
        {
            printf("%i ", right[j]);
            j++;
        }
    }
    printf("\n");
}
